    BaniLine(id = "shabad-hazare-14", gurmukhi = "ਭਾਗੁ ਹੋਆ; ਗੁਰਿ ਸੰਤੁ ਮਿਲਾਇਆ ॥", transliteration = "bhaag hoaa; gur sant milaaiaa ||", translation = "By good fortune, I have met the Saint Guru.", hindi = "भागु होआ; गुरि संतु मिलाइआ ॥", punjabi = "ਮੇਰੇ ਭਾਗ ਜਾਗ ਪਏ ਹਨ, ਗੁਰੂ ਨੇ ਮੈਨੂੰ ਸ਼ਾਂਤੀ ਦਾ ਸੋਮਾ ਪਰਮਾਤਮਾ ਮਿਲਾ ਦਿੱਤਾ ਹੈ।", wordMeaning = "ਭਾਗੁ ਹੋਆ = ਕਿਸਮਤਿ ਜਾਗ ਪਈ ਹੈ। ਗੁਰਿ = ਗੁਰੂ ਨੇ। ਸੰਤੁ = ਸ਼ਾਂਤ-ਮੂਰਤੀ ਪ੍ਰਭੂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-15", gurmukhi = "ਪ੍ਰਭੁ ਅਬਿਨਾਸੀ; ਘਰ ਮਹਿ ਪਾਇਆ ॥", transliteration = "prabh abinaasee; ghar mah paaiaa ||", translation = "I have found the Immortal Lord within the home of my own self.", hindi = "प्रभु अबिनासी; घर महि पाइआ ॥", punjabi = "(ਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਉਸ) ਅਬਿਨਾਸੀ ਪ੍ਰਭੂ ਨੂੰ ਮੈਂ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਹੀ ਲੱਭ ਲਿਆ ਹੈ।", wordMeaning = "ਅਬਿਨਾਸੀ = ਨਾਸ-ਰਹਿਤ। ਘਰ ਮਹਿ = ਹਿਰਦੇ ਵਿਚ (ਹੀ)।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-16", gurmukhi = "ਸੇਵ ਕਰੀ. ਪਲੁ ਚਸਾ, ਨ ਵਿਛੁੜਾ; ਜਨ ਨਾਨਕ ਦਾਸ ਤੁਮਾਰੇ ਜੀਉ ॥੪॥", transliteration = "sev kree. pal chsaa, na vichhuraa; jan naanak daas tumaare jeeu ||4||", translation = "I will now serve You forever, and I shall never be separated from You, even for an instant. Servant Nanak is Your slave, O Beloved Master. ||4||", hindi = "सेव करी. पलु चसा, न विछुड़ा; जन नानक दास तुमारे जीउ ॥४॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! (ਆਖ-ਹੇ ਪ੍ਰਭੂ! ਮਿਹਰ ਕਰ) ਮੈਂ ਤੇਰੇ ਦਾਸਾਂ ਦੀ (ਨਿੱਤ) ਸੇਵਾ ਕਰਦਾ ਰਹਾਂ, (ਤੇਰੇ ਦਾਸਾਂ ਤੋਂ) ਮੈਂ ਇਕ ਪਲ ਭਰ ਭੀ ਨਾਹ ਵਿੱਛੁੜਾਂ, ਇਕ ਚਸਾ-ਭਰ ਭੀ ਨਾਹ ਵਿੱਛੁੜਾਂ ॥੪॥", wordMeaning = "ਕਰੀ = ਕਰੀਂ, ਮੈਂ ਕਰਦਾ ਹਾਂ। ਚਸਾ = ਪਲ ਦਾ ਤ੍ਰੀਹਵਾਂ ਹਿੱਸਾ। ਵਿਛੁੜਾ = ਵਿੱਛੁੜਾਂ, ਮੈਂ ਵਿੱਛੁੜਦਾ ॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-17", gurmukhi = "ਹਉ ਘੋਲੀ ਜੀਉ ਘੋਲਿ ਘੁਮਾਈ; ਜਨ ਨਾਨਕ ਦਾਸ ਤੁਮਾਰੇ ਜੀਉ ॥ ਰਹਾਉ ॥੧॥੮॥", transliteration = "hau gholee jeeu ghol ghumaaee; jan naanak daas tumaare jeeu || rhaau ||1||8||", translation = "I am a sacrifice, my soul is a sacrifice; servant Nanak is Your slave, Lord. ||Pause||1||8||", hindi = "हउ घोली जीउ घोलि घुमाई; जन नानक दास तुमारे जीउ ॥ रहाउ ॥१॥८॥", punjabi = "ਹੇ ਦਾਸ ਨਾਨਕ! (ਆਖ-ਹੇ ਪ੍ਰਭੂ!) ਮੈਂ ਤੇਰੇ ਦਾਸਾਂ ਤੋਂ ਸਦਕੇ ਹਾਂ ਕੁਰਬਾਨ ਹਾਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-18", gurmukhi = "ਧਨਾਸਰੀ ਮਹਲਾ ੧ ਘਰੁ ੧ ਚਉਪਦੇ ॥", transliteration = "dhanaasree mahlaa 1 ghar 1 chaupde ||", translation = "Dhanaasaree, First Mehl, First House, Chau-Padhay:", hindi = "धनासरी महला १ घरु १ चउपदे ॥", punjabi = "ਰਾਗ ਧਨਾਸਰੀ, ਘਰ ੧ ਵਿੱਚ ਗੁਰੂ ਨਾਨਕਦੇਵ ਜੀ ਦੀ ਚਾਰ-ਬੰਦਾਂ ਵਾਲੀ ਬਾਣੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-19", gurmukhi = "ੴ ਸਤਿ ਨਾਮੁ ਕਰਤਾ ਪੁਰਖੁ ਨਿਰਭਉ ਨਿਰਵੈਰੁ ਅਕਾਲ ਮੂਰਤਿ ਅਜੂਨੀ ਸੈਭੰ ਗੁਰ ਪ੍ਰਸਾਦਿ ॥", transliteration = "ik oankar sat naam kartaa purakh nirabhau nirvair akaal moorat ajoonee saibhan gur prasaad ||", translation = "One Universal Creator God. Truth Is The Name. Creative Being Personified. No Fear. No Hatred. Image Of The Undying. Beyond Birth. Self-Existent. By Guru's Grace:", hindi = "एकओंकार सति नामु करता पुरखु निरभउ निरवैरु अकाल मूरति अजूनी सैभं गुर प्रसादि ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਇੱਕ ਹੈ, ਜਿਸ ਦਾ ਨਾਮ 'ਹੋਂਦ ਵਾਲਾ' ਹੈ ਜੋ ਸ੍ਰਿਸ਼ਟੀ ਦਾ ਰਚਨਹਾਰ ਹੈ, ਜੋ ਸਭ ਵਿਚ ਵਿਆਪਕ ਹੈ, ਭੈ ਤੋਂ ਰਹਿਤ ਹੈ, ਵੈਰ-ਰਹਿਤ ਹੈ, ਜਿਸ ਦਾ ਸਰੂਪ ਕਾਲ ਤੋਂ ਪਰੇ ਹੈ, (ਭਾਵ, ਜਿਸ ਦਾ ਸਰੀਰ ਨਾਸ-ਰਹਿਤ ਹੈ), ਜੋ ਜੂਨਾਂ ਵਿਚ ਨਹੀਂ ਆਉਂਦਾ, ਜਿਸ ਦਾ ਪ੍ਰਕਾਸ਼ ਆਪਣੇ ਆਪ ਤੋਂ ਹੋਇਆ ਹੈ ਅਤੇ ਜੋ ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮਿਲਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-20", gurmukhi = "ਜੀਉ ਡਰਤੁ ਹੈ ਆਪਣਾ; ਕੈ ਸਿਉ ਕਰੀ ਪੁਕਾਰ ॥", transliteration = "jeeu darat hai aapnaa; kai siu kree pukaar ||", translation = "My soul is afraid; to whom should I complain?", hindi = "जीउ डरतु है आपणा; कै सिउ करी पुकार ॥", punjabi = "(ਜਗਤ ਦੁੱਖਾਂ ਦਾ ਸਮੁੰਦਰ ਹੈ, ਇਹਨਾਂ ਦੁੱਖਾਂ ਨੂੰ ਵੇਖ ਕੇ) ਮੇਰੀ ਜਿੰਦ ਕੰਬਦੀ ਹੈ (ਪਰਮਾਤਮਾ ਤੋਂ ਬਿਨਾ ਹੋਰ ਕੋਈ ਬਚਾਣ ਵਾਲਾ ਦਿੱਸਦਾ ਨਹੀਂ) ਜਿਸ ਦੇ ਪਾਸ ਮੈਂ ਮਿੰਨਤਾਂ ਕਰਾਂ।", wordMeaning = "ਜੀਉ = ਜਿੰਦ। ਕੈ ਸਿਉ = ਕਿਸ ਪਾਸ? ਕਰੀ = ਮੈਂ ਕਰਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-21", gurmukhi = "ਦੂਖ ਵਿਸਾਰਣੁ ਸੇਵਿਆ; ਸਦਾ ਸਦਾ ਦਾਤਾਰੁ ॥੧॥", transliteration = "dookh visaaran seviaa; sdaa sdaa daataar ||1||", translation = "I serve Him, who makes me forget my pains; He is the Giver, forever and ever. ||1||", hindi = "दूख विसारणु सेविआ; सदा सदा दातारु ॥१॥", punjabi = "(ਸੋ, ਹੋਰ ਆਸਰੇ ਛੱਡ ਕੇ) ਮੈਂ ਦੁੱਖਾਂ ਦੇ ਨਾਸ ਕਰਨ ਵਾਲੇ ਪ੍ਰਭੂ ਨੂੰ ਹੀ ਸਿਮਰਦਾ ਹਾਂ, ਉਹ ਸਦਾ ਹੀ ਬਖ਼ਸ਼ਸ਼ਾਂ ਕਰਨ ਵਾਲਾ ਹੈ ॥੧॥", wordMeaning = "ਦੂਖ ਵਿਸਾਰਣੁ = ਦੁੱਖ ਦੂਰ ਕਰਨ ਵਾਲਾ ਪ੍ਰਭੂ। ਸੇਵਿਆ = ਮੈਂ ਸਿਮਰਿਆ ਹੈ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-22", gurmukhi = "ਸਾਹਿਬੁ ਮੇਰਾ ਨੀਤ ਨਵਾ; ਸਦਾ ਸਦਾ ਦਾਤਾਰੁ ॥੧॥ ਰਹਾਉ ॥", transliteration = "saahib meraa neet nvaa; sdaa sdaa daataar ||1|| rhaau ||", translation = "My Lord and Master is forever new; He is the Giver, forever and ever. ||1||Pause||", hindi = "साहिबु मेरा नीत नवा; सदा सदा दातारु ॥१॥ रहाउ ॥", punjabi = "(ਫਿਰ ਉਹ) ਮੇਰਾ ਮਾਲਿਕ ਸਦਾ ਹੀ ਬਖ਼ਸ਼ਸ਼ਾਂ ਤਾਂ ਕਰਦਾ ਰਹਿੰਦਾ ਹੈ (ਪਰ ਉਹ ਮੇਰੇ ਨਿੱਤ ਦੇ ਤਰਲੇ ਸੁਣ ਕੇ ਕਦੇ ਅੱਕਦਾ ਨਹੀਂ, ਬਖ਼ਸ਼ਸ਼ਾਂ ਵਿਚ) ਨਿੱਤ ਇਉਂ ਹੈ ਜਿਵੇਂ ਪਹਿਲੀ ਵਾਰੀ ਹੀ ਬਖ਼ਸ਼ਸ਼ ਕਰਨ ਲੱਗਾ ਹੈ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਨੀਤ = ਨਿੱਤ। ਨਵਾ = (ਭਾਵ, ਦਾਤਾਂ ਦੇ ਦੇ ਕੇ ਅੱਕਣ ਵਾਲਾ ਨਹੀਂ)। ਦਾਤਾਰੁ = ਦਾਤਾਂ ਦੇਣ ਵਾਲਾ ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-23", gurmukhi = "ਅਨਦਿਨੁ ਸਾਹਿਬੁ ਸੇਵੀਐ; ਅੰਤਿ ਛਡਾਏ ਸੋਇ ॥", transliteration = "andin saahib seveeai; ant chhdaae soi ||", translation = "Night and day, I serve my Lord and Master; He shall save me in the end.", hindi = "अनदिनु साहिबु सेवीऐ; अंति छडाए सोइ ॥", punjabi = "ਹੇ ਮੇਰੀ ਜਿੰਦੇ! ਹਰ ਰੋਜ਼ ਉਸ ਮਾਲਿਕ ਨੂੰ ਯਾਦ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ (ਦੁੱਖਾਂ ਵਿਚੋਂ) ਆਖ਼ਰ ਉਹੀ ਬਚਾਂਦਾ ਹੈ।", wordMeaning = "ਅਨਦਿਨੁ = ਹਰ ਰੋਜ਼, ਸਦਾ। ਅੰਤਿ = ਆਖ਼ਰ ਨੂੰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-24", gurmukhi = "ਸੁਣਿ ਸੁਣਿ ਮੇਰੀ ਕਾਮਣੀ; ਪਾਰਿ ਉਤਾਰਾ ਹੋਇ ॥੨॥", transliteration = "sun sun meree kaamnee; paar utaaraa hoi ||2||", translation = "Hearing and listening, O my dear sister, I have crossed over. ||2||", hindi = "सुणि सुणि मेरी कामणी; पारि उतारा होइ ॥२॥", punjabi = "ਹੇ ਜਿੰਦੇ! ਧਿਆਨ ਨਾਲ ਸੁਣ (ਉਸ ਮਾਲਿਕ ਦਾ ਆਸਰਾ ਲਿਆਂ ਹੀ ਦੁੱਖਾਂ ਦੇ ਸਮੁੰਦਰ ਵਿਚੋਂ) ਪਾਰ ਲੰਘ ਸਕੀਦਾ ਹੈ ॥੨॥", wordMeaning = "ਮੇਰੀ ਕਾਮਣੀ = ਹੇ ਮੇਰੀ ਜਿੰਦੇ! ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-25", gurmukhi = "ਦਇਆਲ; ਤੇਰੈ ਨਾਮਿ ਤਰਾ ॥", transliteration = "daiaal; terai naam traa ||", translation = "O Merciful Lord, Your Name carries me across.", hindi = "दइआल; तेरै नामि तरा ॥", punjabi = "ਹੇ ਦਿਆਲ ਪ੍ਰਭੂ! (ਮੇਹਰ ਕਰ, ਆਪਣਾ ਨਾਮ ਦੇਹ, ਤਾ ਕਿ) ਤੇਰੇ ਨਾਮ ਦੀ ਰਾਹੀਂ ਮੈਂ (ਦੁੱਖਾਂ ਦੇ ਇਸ ਸਮੁੰਦਰ ਵਿਚੋਂ) ਪਾਰ ਲੰਘ ਸਕਾਂ।", wordMeaning = "ਦਇਆਲ = ਹੇ ਦਇਆ ਦੇ ਘਰ! ਨਾਮਿ = ਨਾਮ ਦੀ ਰਾਹੀਂ। ਤਰਾ = ਤਰ ਸਕਦਾ ਹਾਂ, ਪਾਰ ਲੰਘ ਸਕਦਾ ਹਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-26", gurmukhi = "ਸਦ ਕੁਰਬਾਣੈ ਜਾਉ ॥੧॥ ਰਹਾਉ ॥", transliteration = "sad kurbaanai jaau ||1|| rhaau ||", translation = "I am forever a sacrifice to You. ||1||Pause||", hindi = "सद कुरबाणै जाउ ॥१॥ रहाउ ॥", punjabi = "ਮੈਂ ਤੈਥੋਂ ਸਦਾ ਸਦਕੇ ਜਾਂਦਾ ਹਾਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-27", gurmukhi = "ਸਰਬੰ ਸਾਚਾ ਏਕੁ ਹੈ; ਦੂਜਾ ਨਾਹੀ ਕੋਇ ॥", transliteration = "saraban saachaa ek hai; doojaa naahee koi ||", translation = "In all the world, there is only the One True Lord; there is no other at all.", hindi = "सरबं साचा एकु है; दूजा नाही कोइ ॥", punjabi = "ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਪਰਮਾਤਮਾ ਹੀ ਸਭ ਥਾਈਂ ਮੌਜੂਦ ਹੈ, ਉਸ ਤੋਂ ਬਿਨਾ ਹੋਰ ਕੋਈ ਨਹੀਂ।", wordMeaning = "ਸਰਬੰ = ਹਰ ਥਾਂ। ਸਾਚਾ = ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-28", gurmukhi = "ਤਾ ਕੀ ਸੇਵਾ ਸੋ ਕਰੇ; ਜਾ ਕਉ ਨਦਰਿ ਕਰੇ ॥੩॥", transliteration = "taa kee sevaa so kre; jaa kau nadar kre ||3||", translation = "He alone serves the Lord, upon whom the Lord casts His Glance of Grace. ||3||", hindi = "ता की सेवा सो करे; जा कउ नदरि करे ॥३॥", punjabi = "ਜਿਸ ਜੀਵ ਉਤੇ ਉਹ ਮੇਹਰ ਦੀ ਨਿਗਾਹ ਕਰਦਾ ਹੈ, ਉਹ ਉਸ ਦਾ ਸਿਮਰਨ ਕਰਦਾ ਹੈ ॥੩॥", wordMeaning = "ਕਉ = ਨੂੰ। ਨਦਰਿ = ਮੇਹਰ ਦੀ ਨਜ਼ਰ। ਕਰੇਇ = ਕਰਦਾ ਹੈ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-29", gurmukhi = "ਤੁਧੁ ਬਾਝੁ ਪਿਆਰੇ; ਕੇਵ ਰਹਾ ॥", transliteration = "tudh baajh piaare; kev rhaa ||", translation = "Without You, O Beloved, how could I even live?", hindi = "तुधु बाझु पिआरे; केव रहा ॥", punjabi = "ਹੇ ਪਿਆਰੇ (ਪ੍ਰਭੂ!) ਤੇਰੀ ਯਾਦ ਤੋਂ ਬਿਨਾ ਮੈਂ ਵਿਆਕੁਲ ਹੋ ਜਾਂਦਾ ਹਾਂ।", wordMeaning = "ਕੇਵ ਰਹਾ = ਕਿਵੇਂ ਰਹਿ ਸਕਦਾ ਹਾਂ? ਮੈਂ ਵਿਆਕੁਲ ਹੋ ਜਾਂਦਾ ਹਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-30", gurmukhi = "ਸਾ ਵਡਿਆਈ ਦੇਹਿ; ਜਿਤੁ ਨਾਮਿ ਤੇਰੇ ਲਾਗਿ ਰਹਾਂ ॥", transliteration = "saa vdiaaee deh; jit naam tere laag rhaan ||", translation = "Bless me with such greatness, that I may remain attached to Your Name.", hindi = "सा वडिआई देहि; जितु नामि तेरे लागि रहां ॥", punjabi = "ਮੈਨੂੰ ਕੋਈ ਉਹ ਵੱਡੀ ਦਾਤਿ ਦੇਹ, ਜਿਸ ਦਾ ਸਦਕਾ ਮੈਂ ਤੇਰੇ ਨਾਮ ਵਿਚ ਜੁੜਿਆ ਰਹਾਂ।", wordMeaning = "ਜਿਤੁ = ਜਿਸ ਦੀ ਰਾਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-31", gurmukhi = "ਦੂਜਾ ਨਾਹੀ ਕੋਇ; ਜਿਸੁ ਆਗੈ ਪਿਆਰੇ ਜਾਇ ਕਹਾ ॥੧॥ ਰਹਾਉ ॥", transliteration = "doojaa naahee koi; jis aagai piaare jaai khaa ||1|| rhaau ||", translation = "There is no other, O Beloved, to whom I can go and speak. ||1||Pause||", hindi = "दूजा नाही कोइ; जिसु आगै पिआरे जाइ कहा ॥१॥ रहाउ ॥", punjabi = "ਹੇ ਪਿਆਰੇ! ਤੈਥੋਂ ਬਿਨਾ ਹੋਰ ਐਸਾ ਕੋਈ ਨਹੀਂ ਹੈ, ਜਿਸ ਪਾਸ ਜਾ ਕੇ ਮੈਂ ਇਹ ਅਰਜ਼ੋਈ ਕਰ ਸਕਾਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਜਾਇ = ਜਾ ਕੇ ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
