    BaniLine(id = "shabad-hazare-44", gurmukhi = "ਜਿਨ ਕੇ ਚੋਲੇ ਰਤੜੇ ਪਿਆਰੇ; ਕੰਤੁ ਤਿਨਾ ਕੈ ਪਾਸਿ ॥", transliteration = "jin ke chole ratre piaare; kant tinaa kai paas ||", translation = "Those whose shawls are so dyed, O Beloved, their Husband Lord is always with them.", hindi = "जिन के चोले रतड़े पिआरे; कंतु तिना कै पासि ॥", punjabi = "ਹੇ ਪਿਆਰੇ (ਸੱਜਣ!) ਜਿਨ੍ਹਾਂ ਜੀਵ-ਇਸਤ੍ਰੀਆਂ ਦੇ (ਸਰੀਰ-) ਚੋਲੇ (ਜੀਵਨ ਨਾਮ-ਰੰਗ ਨਾਲ) ਰੰਗੇ ਗਏ ਹਨ, ਖਸਮ-ਪ੍ਰਭੂ (ਸਦਾ) ਉਹਨਾਂ ਦੇ ਕੋਲ (ਵੱਸਦਾ) ਹੈ।", wordMeaning = "ਰਤੜੇ = ਰੰਗੇ ਹੋਏ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-45", gurmukhi = "ਧੂੜਿ ਤਿਨਾ ਕੀ ਜੇ ਮਿਲੈ. ਜੀ ਕਹੁ; ਨਾਨਕ ਕੀ ਅਰਦਾਸਿ ॥੩॥", transliteration = "dhoor tinaa kee je milai. jee kah; naanak kee ardaas ||3||", translation = "Bless me with the dust of those humble beings, O Dear Lord. Says Nanak, this is my prayer. ||3||", hindi = "धूड़ि तिना की जे मिलै. जी कहु; नानक की अरदासि ॥३॥", punjabi = "ਹੇ ਸੱਜਣ! ਨਾਨਕ ਵਲੋਂ ਉਹਨਾਂ ਪਾਸ ਬੇਨਤੀ ਕਰ, ਭਲਾ ਕਿਤੇ ਨਾਨਕ ਨੂੰ ਉਹਨਾਂ ਦੇ ਚਰਨਾਂ ਦੀ ਧੂੜ ਮਿਲ ਜਾਏ ॥੩॥", wordMeaning = "ਕਹੁ = ਆਖ। ਅਰਦਾਸਿ = ਬੇਨਤੀ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-46", gurmukhi = "ਆਪੇ ਸਾਜੇ ਆਪੇ ਰੰਗੇ; ਆਪੇ ਨਦਰਿ ਕਰੇਇ ॥", transliteration = "aape saaje aape range; aape nadar krei ||", translation = "He Himself creates, and He Himself imbues us. He Himself bestows His Glance of Grace.", hindi = "आपे साजे आपे रंगे; आपे नदरि करेइ ॥", punjabi = "ਜਿਸ ਜੀਵ-ਇਸਤ੍ਰੀ ਉਤੇ ਪ੍ਰਭੂ ਆਪ ਮਿਹਰ ਦੀ ਨਜ਼ਰ ਕਰਦਾ ਹੈ ਉਸ ਨੂੰ ਉਹ ਆਪ ਹੀ ਸੰਵਾਰਦਾ ਹੈ ਆਪ ਹੀ (ਨਾਮ ਦਾ) ਰੰਗ ਚਾੜ੍ਹਦਾ ਹੈ।", wordMeaning = "ਸਾਜੇ = ਸਵਾਰਦਾ ਹੈ। ਨਦਰਿ = ਮਿਹਰ ਦੀ ਨਜ਼ਰ। ਕਰੇਇ = ਕਰਦਾ ਹੈ, ਕਰੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-47", gurmukhi = "ਨਾਨਕ. ਕਾਮਣਿ ਕੰਤੈ ਭਾਵੈ; ਆਪੇ ਹੀ ਰਾਵੇਇ ॥੪॥੧॥੩॥", transliteration = "naanak. kaaman kantai bhaavai; aape hee raavei ||4||1||3||", translation = "O Nanak, if the soul-bride becomes pleasing to her Husband Lord, He Himself enjoys her. ||4||1||3||", hindi = "नानक. कामणि कंतै भावै; आपे ही रावेइ ॥४॥१॥३॥", punjabi = "ਹੇ ਨਾਨਕ! ਉਹ ਜੀਵ-ਇਸਤ੍ਰੀ ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਪਿਆਰੀ ਲੱਗਦੀ ਹੈ, ਉਸ ਨੂੰ ਪ੍ਰਭੂ ਆਪ ਹੀ ਆਪਣੇ ਚਰਨਾਂ ਵਿਚ ਜੋੜਦਾ ਹੈ ॥੪॥੧॥੩॥", wordMeaning = "ਕਾਮਣਿ = ਇਸਤ੍ਰੀ, ਜੀਵ-ਇਸਤ੍ਰੀ। ਰਾਵੇਇ = ਮਾਣਦਾ ਹੈ, ਆਪਣੇ ਨਾਲ ਮਿਲਾਂਦਾ ਹੈ ॥੪॥੧॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-48", gurmukhi = "ਤਿਲੰਗ ਮਃ ੧ ॥", transliteration = "tilang mh 1 ||", translation = "Tilang, First Mehl:", hindi = "तिलंग मः १ ॥", punjabi = "ਤਿਲੰਕ ਪਹਿਲੀ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-49", gurmukhi = "ਇਆਨੜੀਏ; ਮਾਨੜਾ ਕਾਇ ਕਰੇਹਿ ॥", transliteration = "iaanreee; maanraa kaai kreh ||", translation = "O foolish and ignorant soul-bride, why are you so proud?", hindi = "इआनड़ीए; मानड़ा काइ करेहि ॥", punjabi = "ਹੇ ਬਹੁਤ ਅੰਞਾਣ ਜਿੰਦੇ! ਇਤਨਾ ਕੋਝਾ ਮਾਣ ਤੂੰ ਕਿਉਂ ਕਰਦੀ ਹੈਂ?", wordMeaning = "ਇਆਨੀ = ਅੰਞਾਣ ਕੁੜੀ। ਇਆਨੜੀ = ਬਹੁਤ ਅੰਞਾਣ ਕੁੜੀ। ਇਆਨੜੀਏ = ਹੇ ਬਹੁਤ ਅੰਞਾਣ ਜਿੰਦੇ! ਮਾਨੜਾ = ਕੋਝਾ ਮਾਣ। ਕਾਇ = ਕਿਉਂ? ਕਰੇਹਿ = ਤੂੰ ਕਰਦੀ ਹੈਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-50", gurmukhi = "ਆਪਨੜੈ ਘਰਿ ਹਰਿ; ਰੰਗੋ. ਕੀ ਨ ਮਾਣੇਹਿ ॥", transliteration = "aapanrai ghar har; rango. kee na maaneh ||", translation = "Within the home of your own self, why do you not enjoy the Love of your Lord?", hindi = "आपनड़ै घरि हरि; रंगो. की न माणेहि ॥", punjabi = "ਪਰਮਾਤਮਾ ਤੇਰੇ ਆਪਣੇ ਹੀ ਹਿਰਦੇ-ਘਰ ਵਿਚ ਹੈ, ਤੂੰ ਉਸ (ਦੇ ਮਿਲਾਪ) ਦਾ ਆਨੰਦ ਕਿਉਂ ਨਹੀਂ ਮਾਣਦੀ?", wordMeaning = "ਘਰਿ = ਘਰ ਵਿਚ, ਹਿਰਦੇ ਵਿਚ। ਰੰਗੋ = ਰੰਗੁ, ਆਨੰਦ। ਕੀ = ਕਿਉਂ?", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-51", gurmukhi = "ਸਹੁ ਨੇੜੈ. ਧਨ ਕੰਮਲੀਏ; ਬਾਹਰੁ. ਕਿਆ ਢੂਢੇਹਿ ॥", transliteration = "sah nerai. dhan kammleee; baahar. kiaa dhoodheh ||", translation = "Your Husband Lord is so very near, O foolish bride; why do you search for Him outside?", hindi = "सहु नेड़ै. धन कंमलीए; बाहरु. किआ ढूढेहि ॥", punjabi = "ਹੇ ਭੋਲੀ ਜੀਵ-ਇਸਤ੍ਰੀਏ! ਪਤੀ-ਪ੍ਰਭੂ (ਤੇਰੇ ਅੰਦਰ ਹੀ ਤੇਰੇ) ਨੇੜੇ ਵੱਸ ਰਿਹਾ ਹੈ, ਤੂੰ (ਜੰਗਲ ਆਦਿਕ) ਬਾਹਰਲਾ ਸੰਸਾਰ ਕਿਉਂ ਭਾਲਦੀ ਫਿਰਦੀ ਹੈਂ?", wordMeaning = "ਧਨ ਕੰਮਲੀਏ = ਹੇ ਭੋਲੀ ਜੀਵ-ਇਸਤ੍ਰੀਏ! ਬਾਹਰੁ = ਬਾਹਰਲਾ ਜਗਤ {ਨੋਟ: 'ਬਾਹਰਿ' ਅਤੇ 'ਬਾਹਰੁ' ਦਾ ਫ਼ਰਕ ਚੇਤੇ ਰੱਖਣ-ਯੋਗ ਹੈ}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-52", gurmukhi = "ਭੈ ਕੀਆ ਦੇਹਿ ਸਲਾਈਆ ਨੈਣੀ; ਭਾਵ ਕਾ ਕਰਿ ਸੀਗਾਰੋ ॥", transliteration = "bhai keeaa deh slaaeeaa nainee; bhaav kaa kar seegaaro ||", translation = "Apply the Fear of God as the maascara to adorn your eyes, and make the Love of the Lord your ornament.", hindi = "भै कीआ देहि सलाईआ नैणी; भाव का करि सीगारो ॥", punjabi = "(ਜੇ ਤੂੰ ਉਸ ਦਾ ਦੀਦਾਰ ਕਰਨਾ ਹੈ, ਤਾਂ ਆਪਣੀਆਂ ਗਿਆਨ ਦੀਆਂ) ਅੱਖਾਂ ਵਿਚ (ਪ੍ਰਭੂ ਦੇ) ਡਰ-ਅਦਬ (ਦੇ ਸੁਰਮੇ) ਦੀਆਂ ਸਲਾਈਆਂ ਪਾ, ਪ੍ਰਭੂ ਦੇ ਪਿਆਰ ਦਾ ਹਾਰ-ਸਿੰਗਾਰ ਕਰ।", wordMeaning = "ਭਾਵ ਕਾ = ਪ੍ਰੇਮ ਦਾ। ਸਲਾਈ = ਸੁਰਮਚੂ ਜਿਸ ਨਾਲ ਅੱਖਾਂ ਵਿਚ ਸੁਰਮਾ ਪਾਈਦਾ ਹੈ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-53", gurmukhi = "ਤਾ ਸੋਹਾਗਣਿ ਜਾਣੀਐ ਲਾਗੀ; ਜਾ ਸਹੁ ਧਰੇ ਪਿਆਰੋ ॥੧॥", transliteration = "taa sohaagan jaaneeai laagee; jaa sah dhre piaaro ||1||", translation = "Then, you shall be known as a devoted and committed soul-bride, when you enshrine love for your Husband Lord. ||1||", hindi = "ता सोहागणि जाणीऐ लागी; जा सहु धरे पिआरो ॥१॥", punjabi = "ਜੀਵ-ਇਸਤ੍ਰੀ ਤਦੋਂ ਹੀ ਸੋਹਾਗ ਭਾਗ ਵਾਲੀ ਤੇ ਪ੍ਰਭੂ-ਚਰਨਾਂ ਵਿਚ ਜੁੜੀ ਹੋਈ ਸਮਝੀ ਜਾਂਦੀ ਹੈ, ਜਦੋਂ ਪ੍ਰਭੂ-ਪਤੀ ਉਸ ਨਾਲ ਪਿਆਰ ਕਰੇ ॥੧॥", wordMeaning = "ਲਾਗੀ = ਲੱਗੀ ਹੋਈ, ਜੁੜੀ ਹੋਈ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-54", gurmukhi = "ਇਆਣੀ ਬਾਲੀ ਕਿਆ ਕਰੇ; ਜਾ ਧਨ. ਕੰਤ ਨ ਭਾਵੈ ॥", transliteration = "iaanee baalee kiaa kre; jaa dhan. kant na bhaavai ||", translation = "What can the silly young bride do, if she is not pleasing to her Husband Lord?", hindi = "इआणी बाली किआ करे; जा धन. कंत न भावै ॥", punjabi = "(ਪਰ) ਅੰਞਾਣ ਜੀਵ-ਇਸਤ੍ਰੀ ਭੀ ਕੀਹ ਕਰ ਸਕਦੀ ਹੈ ਜੇ ਉਹ ਜੀਵ-ਇਸਤ੍ਰੀ ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਚੰਗੀ ਹੀ ਨਾਹ ਲੱਗੇ?", wordMeaning = "ਕਿਆ ਕਰੇ = ਕੀਹ ਕਰ ਸਕਦੀ ਹੈ? ਕੰਤ ਨ ਭਾਵੈ = ਕੰਤ ਨੂੰ ਚੰਗੀ ਨਾਹ ਲੱਗੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-55", gurmukhi = "ਕਰਣ ਪਲਾਹ ਕਰੇ ਬਹੁਤੇਰੇ; ਸਾ ਧਨ. ਮਹਲੁ ਨ ਪਾਵੈ ॥", transliteration = "karan plaah kre bhutere; saa dhan. mahal na paavai ||", translation = "She may plead and implore so many times, but still, such a bride shall not obtain the Mansion of the Lord's Presence.", hindi = "करण पलाह करे बहुतेरे; सा धन. महलु न पावै ॥", punjabi = "ਅਜੇਹੀ ਜੀਵ-ਇਸਤ੍ਰੀ ਭਾਵੇਂ ਕਿਤਨੇ ਹੀ ਤਰਲੇ ਪਈ ਕਰੇ, ਉਹ ਪਤੀ-ਪ੍ਰਭੂ ਦਾ ਮਹਲ-ਘਰ ਲੱਭ ਹੀ ਨਹੀਂ ਸਕਦੀ।", wordMeaning = "ਕਰਣ ਪਲਾਹ = {करूणाप्रलाप} ਤਰਲੇ, ਕੀਰਨੇ। ਸਾਧਨ = ਜੀਵ-ਇਸਤ੍ਰੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-56", gurmukhi = "ਵਿਣੁ ਕਰਮਾ. ਕਿਛੁ ਪਾਈਐ ਨਾਹੀ; ਜੇ ਬਹੁਤੇਰਾ ਧਾਵੈ ॥", transliteration = "vin karmaa. kichh paaeeai naahee; je bhuteraa dhaavai ||", translation = "Without the karma of good deeds, nothing is obtained, although she may run around frantically.", hindi = "विणु करमा. किछु पाईऐ नाही; जे बहुतेरा धावै ॥", punjabi = "(ਅਸਲ ਗੱਲ ਇਹ ਹੈ ਕਿ) ਜੀਵ-ਇਸਤ੍ਰੀ ਭਾਵੇਂ ਕਿਤਨੀ ਹੀ ਦੌੜ-ਭੱਜ ਕਰੇ, ਪ੍ਰਭੂ ਦੀ ਮੇਹਰ ਦੀ ਨਜ਼ਰ ਤੋਂ ਬਿਨਾ ਕੁਝ ਭੀ ਹਾਸਲ ਨਹੀਂ ਹੁੰਦਾ।", wordMeaning = "ਕਰਮਾ = ਕਰਮ, ਬਖ਼ਸ਼ਸ਼। ਧਾਵੈ = ਦੌੜ-ਭੱਜ ਕਰੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-57", gurmukhi = "ਲਬ ਲੋਭ ਅਹੰਕਾਰ ਕੀ ਮਾਤੀ; ਮਾਇਆ ਮਾਹਿ ਸਮਾਣੀ ॥", transliteration = "lab lobh ahankaar kee maatee; maaiaa maah smaanee ||", translation = "She is intoxicated with greed, pride and egotism, and engrossed in Maya.", hindi = "लब लोभ अहंकार की माती; माइआ माहि समाणी ॥", punjabi = "ਜੇ ਜੀਵ-ਇਸਤ੍ਰੀ ਜੀਭ ਦੇ ਚਸਕੇ ਲਾਲਚ ਤੇ ਅਹੰਕਾਰ (ਆਦਿਕ) ਵਿਚ ਹੀ ਮਸਤ ਰਹੇ, ਅਤੇ ਸਦਾ ਮਾਇਆ (ਦੇ ਮੋਹ) ਵਿਚ ਡੁੱਬੀ ਰਹੇ,", wordMeaning = "ਮਾਤੀ = ਮੱਤੀ ਹੋਈ, ਮਸਤ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-58", gurmukhi = "ਇਨੀ ਬਾਤੀ. ਸਹੁ ਪਾਈਐ ਨਾਹੀ; ਭਈ ਕਾਮਣਿ ਇਆਣੀ ॥੨॥", transliteration = "inee baatee. sah paaeeai naahee; bhaee kaaman iaanee ||2||", translation = "She cannot obtain her Husband Lord in these ways; the young bride is so foolish! ||2||", hindi = "इनी बाती. सहु पाईऐ नाही; भई कामणि इआणी ॥२॥", punjabi = "ਤਾਂ ਇਹਨੀਂ ਗੱਲੀਂ ਖਸਮ ਪ੍ਰਭੂ ਨਹੀਂ ਮਿਲਦਾ। ਉਹ ਜੀਵ-ਇਸਤ੍ਰੀ ਅੰਞਾਣ ਹੀ ਰਹੀ (ਜੋ ਵਿਕਾਰਾਂ ਵਿਚ ਭੀ ਮਸਤ ਰਹੇ ਤੇ ਫਿਰ ਭੀ ਸਮਝੇ ਕਿ ਉਹ ਪਤੀ-ਪ੍ਰਭੂ ਨੂੰ ਪ੍ਰਸੰਨ ਕਰ ਸਕਦੀ ਹੈ) ॥੨॥", wordMeaning = "ਇਨੀ ਬਾਤੀ = ਇਹਨਾਂ ਗੱਲਾਂ ਨਾਲ। ਕਾਮਣਿ = ਇਸਤ੍ਰੀ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-59", gurmukhi = "ਜਾਇ ਪੁਛਹੁ. ਸੋਹਾਗਣੀ ਵਾਹੈ; ਕਿਨੀ ਬਾਤੀ. ਸਹੁ ਪਾਈਐ ॥", transliteration = "jaai puchhah. sohaagnee vaahai; kinee baatee. sah paaeeai ||", translation = "Go and ask the happy, pure soul-brides, how did they obtain their Husband Lord?", hindi = "जाइ पुछहु. सोहागणी वाहै; किनी बाती. सहु पाईऐ ॥", punjabi = "(ਜਿਨ੍ਹਾਂ ਨੂੰ ਪਤੀ-ਪ੍ਰਭੂ ਮਿਲ ਪਿਆ ਹੈ, ਬੇਸ਼ਕ) ਉਹਨਾਂ ਸੁਹਾਗ ਭਾਗ ਵਾਲੀਆਂ ਨੂੰ ਜਾ ਕੇ ਪੁੱਛ ਵੇਖੋ ਕਿ ਕਿਹਨੀਂ ਗੱਲੀਂ ਖਸਮ-ਪ੍ਰਭੂ ਮਿਲਦਾ ਹੈ,", wordMeaning = "ਵਾਹੈ = ਉਹਨਾਂ ਨੂੰ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-60", gurmukhi = "ਜੋ ਕਿਛੁ ਕਰੇ. ਸੋ ਭਲਾ ਕਰਿ ਮਾਨੀਐ; ਹਿਕਮਤਿ ਹੁਕਮੁ ਚੁਕਾਈਐ ॥", transliteration = "jo kichh kre. so bhlaa kar maaneeai; hikamat hukam chukaaeeai ||", translation = "Whatever the Lord does, accept that as good; do away with your own cleverness and self-will.", hindi = "जो किछु करे. सो भला करि मानीऐ; हिकमति हुकमु चुकाईऐ ॥", punjabi = "(ਉਹ ਇਹੀ ਉੱਤਰ ਦੇਂਦੀਆਂ ਹਨ ਕਿ) ਚਲਾਕੀ ਤੇ ਧੱਕਾ ਛੱਡ ਦਿਉ, ਜੋ ਕੁਝ ਪ੍ਰਭੂ ਕਰਦਾ ਹੈ ਉਸ ਨੂੰ ਚੰਗਾ ਸਮਝ ਕੇ (ਸਿਰ ਮੱਥੇ ਤੇ) ਮੰਨੋ,", wordMeaning = "ਹਿਕਮਤਿ = ਚਲਾਕੀ। ਹੁਕਮੁ = ਧੱਕਾ, ਵਧੀਕੀ, ਜੋਰਾਵਰੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-61", gurmukhi = "ਜਾ ਕੈ. ਪ੍ਰੇਮਿ ਪਦਾਰਥੁ ਪਾਈਐ; ਤਉ ਚਰਣੀ ਚਿਤੁ ਲਾਈਐ ॥", transliteration = "jaa kai. prem pdaarath paaeeai; tau charnee chit laaeeai ||", translation = "By His Love, true wealth is obtained; link your consciousness to His lotus feet.", hindi = "जा कै. प्रेमि पदारथु पाईऐ; तउ चरणी चितु लाईऐ ॥", punjabi = "ਜਿਸ ਪ੍ਰਭੂ ਦੇ ਪ੍ਰੇਮ ਦਾ ਸਦਕਾ ਨਾਮ-ਵਸਤ ਮਿਲਦੀ ਹੈ ਉਸ ਦੇ ਚਰਨਾਂ ਵਿਚ ਮਨ ਜੋੜੋ,", wordMeaning = "ਜਾ ਕੈ ਪ੍ਰੇਮਿ = ਜਿਸ ਦੇ ਪ੍ਰੇਮ ਦੀ ਰਾਹੀਂ। ਤਉ = ਉਸ ਦੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-62", gurmukhi = "ਸਹੁ ਕਹੈ ਸੋ ਕੀਜੈ. ਤਨੁ ਮਨੋ ਦੀਜੈ; ਐਸਾ ਪਰਮਲੁ ਲਾਈਐ ॥", transliteration = "sah khai so keejai. tan mno deejai; aisaa paramal laaeeai ||", translation = "As your Husband Lord directs, so you must act; surrender your body and mind to Him, and apply this perfume to yourself.", hindi = "सहु कहै सो कीजै. तनु मनो दीजै; ऐसा परमलु लाईऐ ॥", punjabi = "ਖਸਮ-ਪ੍ਰਭੂ ਜੋ ਹੁਕਮ ਕਰਦਾ ਹੈ ਉਹ ਕਰੋ, ਆਪਣਾ ਸਰੀਰ ਤੇ ਮਨ ਉਸ ਦੇ ਹਵਾਲੇ ਕਰੋ, ਬੱਸ! ਇਹ ਸੁਗੰਧੀ (ਜਿੰਦ ਵਾਸਤੇ) ਵਰਤੋ।", wordMeaning = "ਮਨੋ = ਮਨੁ। ਪਰਮਲੁ = ਸੁਗੰਧੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-63", gurmukhi = "ਏਵ ਕਹਹਿ ਸੋਹਾਗਣੀ ਭੈਣੇ; ਇਨੀ ਬਾਤੀ ਸਹੁ ਪਾਈਐ ॥੩॥", transliteration = "ev kahah sohaagnee bhaine; inee baatee sah paaeeai ||3||", translation = "So speaks the happy soul-bride, O sister; in this way, the Husband Lord is obtained. ||3||", hindi = "एव कहहि सोहागणी भैणे; इनी बाती सहु पाईऐ ॥३॥", punjabi = "ਸੋਹਾਗ ਭਾਗ ਵਾਲੀਆਂ ਇਹੀ ਆਖਦੀਆਂ ਹਨ ਕਿ ਹੇ ਭੈਣ! ਇਹਨੀਂ ਗੱਲੀਂ ਹੀ ਖਸਮ-ਪ੍ਰਭੂ ਮਿਲਦਾ ਹੈ ॥੩॥", wordMeaning = "ਏਵ = ਇਸ ਤਰ੍ਹਾਂ। ਕਹਹਿ = ਕਹਿੰਦੀਆਂ ਹਨ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-64", gurmukhi = "ਆਪੁ ਗਵਾਈਐ. ਤਾ ਸਹੁ ਪਾਈਐ; ਅਉਰੁ ਕੈਸੀ ਚਤੁਰਾਈ ॥", transliteration = "aap gvaaeeai. taa sah paaeeai; aur kaisee chturaaee ||", translation = "Give up your selfhood, and so obtain your Husband Lord; what other clever tricks are of any use?", hindi = "आपु गवाईऐ. ता सहु पाईऐ; अउरु कैसी चतुराई ॥", punjabi = "ਖਸਮ-ਪ੍ਰਭੂ ਤਦੋਂ ਹੀ ਮਿਲਦਾ ਹੈ ਜਦੋਂ ਆਪਾ-ਭਾਵ ਦੂਰ ਕਰੀਏ। ਇਸ ਤੋਂ ਬਿਨਾ ਕੋਈ ਹੋਰ ਉੱਦਮ ਵਿਅਰਥ ਚਲਾਕੀ ਹੈ।", wordMeaning = "ਆਪੁ = ਆਪਾ-ਭਾਵ। ਅਉਰੁ = ਕੋਈ ਹੋਰ ਉੱਦਮ। ਕੈਸੀ ਚਤੁਰਾਈ = ਵਿਅਰਥ ਚਲਾਕੀ।", startsAtMs = 0L, endsAtMs = 0L)
)

private fun generatedShabadHazareLines2(): List<BaniLine> = listOf(
    BaniLine(id = "shabad-hazare-65", gurmukhi = "ਸਹੁ ਨਦਰਿ ਕਰਿ ਦੇਖੈ. ਸੋ ਦਿਨੁ ਲੇਖੈ; ਕਾਮਣਿ ਨਉ ਨਿਧਿ ਪਾਈ ॥", transliteration = "sah nadar kar dekhai. so din lekhai; kaaman nau nidh paaee ||", translation = "When the Husband Lord looks upon the soul-bride with His Gracious Glance, that day is historic - the bride obtains the nine treasures.", hindi = "सहु नदरि करि देखै. सो दिनु लेखै; कामणि नउ निधि पाई ॥", punjabi = "(ਜ਼ਿੰਦਗੀ ਦਾ) ਉਹ ਦਿਨ ਸਫਲ ਜਾਣੋ ਜਦੋਂ ਪਤੀ-ਪ੍ਰਭੂ ਮੇਹਰ ਦੀ ਨਿਹਾਗ ਨਾਲ ਤੱਕੇ, (ਜਿਸ) ਜੀਵ-ਇਸਤ੍ਰੀ (ਵਲ ਮੇਹਰ ਦੀ) ਨਿਗਾਹ ਕਰਦਾ ਹੈ ਉਹ ਮਾਨੋ ਨੌ ਖ਼ਜ਼ਾਨੇ ਲੱਭ ਲੈਂਦੀ ਹੈ।", wordMeaning = "ਲੇਖੈ = ਲੇਖੇ ਵਿਚ, ਸਫਲ। ਨਉਨਿਧਿ = ਨੌ ਖ਼ਜ਼ਾਨੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-66", gurmukhi = "ਆਪਣੇ ਕੰਤ ਪਿਆਰੀ. ਸਾ ਸੋਹਾਗਣਿ; ਨਾਨਕ. ਸਾ ਸਭਰਾਈ ॥", transliteration = "aapne kant piaaree. saa sohaagan; naanak. saa sabhraaee ||", translation = "She who is loved by her Husband Lord, is the true soul-bride; O Nanak, she is the queen of all.", hindi = "आपणे कंत पिआरी. सा सोहागणि; नानक. सा सभराई ॥", punjabi = "ਹੇ ਨਾਨਕ! ਜੇਹੜੀ ਜੀਵ-ਇਸਤ੍ਰੀ ਆਪਣੇ ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਪਿਆਰੀ ਹੈ ਉਹ ਸੁਹਾਗ ਭਾਗ ਵਾਲੀ ਹੈ ਉਹ (ਜਗਤ-) ਪਰਵਾਰ ਵਿਚ ਆਦਰ-ਮਾਣ ਪ੍ਰਾਪਤ ਕਰਦੀ ਹੈ।", wordMeaning = "ਸਭਰਾਈ = ਭਰਾਵਾਂ ਵਾਲੀ, ਸਾਰੇ ਪਰਵਾਰ ਵਿਚ ਆਦਰ ਵਾਲੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-67", gurmukhi = "ਐਸੈ ਰੰਗਿ ਰਾਤੀ. ਸਹਜ ਕੀ ਮਾਤੀ; ਅਹਿਨਿਸਿ ਭਾਇ ਸਮਾਣੀ ॥", transliteration = "aisai rang raatee. sahaj kee maatee; ahinis bhaai smaanee ||", translation = "Thus she is imbued with His Love, intoxicated with delight; day and night, she is absorbed in His Love.", hindi = "ऐसै रंगि राती. सहज की माती; अहिनिसि भाइ समाणी ॥", punjabi = "ਜੇਹੜੀ ਪ੍ਰਭੂ ਦੇ ਪਿਆਰ-ਰੰਗ ਵਿਚ ਰੰਗੀ ਰਹਿੰਦੀ ਹੈ, ਜੇਹੜੀ ਅਡੋਲਤਾ ਵਿਚ ਮਸਤ ਰਹਿੰਦੀ ਹੈ, ਜੇਹੜੀ ਦਿਨ ਰਾਤ ਪ੍ਰਭੂ ਦੇ ਪ੍ਰੇਮ ਵਿਚ ਮਗਨ ਰਹਿੰਦੀ ਹੈ,", wordMeaning = "ਰੰਗਿ = ਰੰਗ ਵਿਚ। ਰਾਤੀ = ਰੱਤੀ ਹੋਈ, ਰੰਗੀ ਹੋਈ। ਅਹਿ = ਦਿਨ। ਨਿਸਿ = ਰਾਤ। ਭਾਇ = ਭਾਉ ਵਿਚ, ਪ੍ਰੇਮ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-68", gurmukhi = "ਸੁੰਦਰਿ ਸਾਇ ਸਰੂਪ ਬਿਚਖਣਿ; ਕਹੀਐ ਸਾ ਸਿਆਣੀ ॥੪॥੨॥੪॥", transliteration = "sundar saai sroop bichakhan; kheeai saa siaanee ||4||2||4||", translation = "She is beautiful, glorious and brilliant; she is known as truly wise. ||4||2||4||", hindi = "सुंदरि साइ सरूप बिचखणि; कहीऐ सा सिआणी ॥४॥२॥४॥", punjabi = "ਉਹੀ ਸੋਹਣੀ ਹੈ ਸੋਹਣੇ ਰੂਪ ਵਾਲੀ ਹੈ ਅਕਲ ਵਾਲੀ ਹੈ ਤੇ ਸਿਆਣੀ ਕਹੀ ਜਾਂਦੀ ਹੈ ॥੪॥੨॥੪॥", wordMeaning = "ਸੁੰਦਰਿ = ਸੁੰਦਰੀ, ਸੋਹਣੀ। ਸਾਈ = ਉਹੀ ਇਸਤ੍ਰੀ। ਸਰੂਪ = ਰੂਪ ਵਾਲੀ। ਬਿਚਖਣਿ = ਅਕਲ ਵਾਲੀ {विचक्षण = ਤੀਖਣ-ਬੁਧਿ}। ਸਾ = ਉਹ ਇਸਤ੍ਰੀ ॥੪॥੨॥੪॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-69", gurmukhi = "ਸੂਹੀ ਮਹਲਾ ੧ ॥", transliteration = "soohee mahlaa 1 ||", translation = "Soohee, First Mehl:", hindi = "सूही महला १ ॥", punjabi = "ਸੂਹੀ ਪਹਿਲੀ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-70", gurmukhi = "ਕਉਣ ਤਰਾਜੀ. ਕਵਣੁ ਤੁਲਾ; ਤੇਰਾ ਕਵਣੁ ਸਰਾਫੁ ਬੁਲਾਵਾ ॥", transliteration = "kaun traajee. kavan tulaa; teraa kavan sraaph bulaavaa ||", translation = "What scale, what weights, and what assayer shall I call for You, Lord?", hindi = "कउण तराजी. कवणु तुला; तेरा कवणु सराफु बुलावा ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਕੋਈ ਐਸੀ ਤੱਕੜੀ ਨਹੀਂ ਕੋਈ ਐਸਾ ਵੱਟਾ ਨਹੀਂ (ਜੋ ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਦਾਜ਼ਾ ਲਾ ਸਕਣ), ਕੋਈ ਐਸਾ ਸਰਾਫ਼ ਨਹੀਂ ਜਿਸ ਨੂੰ ਮੈਂ (ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਦਾਜ਼ਾ ਲਾਣ ਵਾਸਤੇ) ਸੱਦ ਸਕਾਂ।", wordMeaning = "ਕਉਣ = ਕੇਹੜੀ? ਤਰਾਜੀ = ਤੱਕੜੀ। ਕਵਣੁ = ਕੇਹੜਾ? ਤੁਲਾ = ਵੱਟਾ। ਸਰਾਫੁ = ਮੁੱਲ ਪਾਣ ਵਾਲਾ, ਪਰਖ ਕਰਨ ਵਾਲਾ। ਬੁਲਾਵਾ = ਬੁਲਾਵਾਂ, ਮੈਂ ਸੱਦਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-71", gurmukhi = "ਕਉਣੁ ਗੁਰੂ. ਕੈ ਪਹਿ ਦੀਖਿਆ ਲੇਵਾ; ਕੈ ਪਹਿ ਮੁਲੁ ਕਰਾਵਾ ॥੧॥", transliteration = "kaun guroo. kai pah deekhiaa levaa; kai pah mul kraavaa ||1||", translation = "From what guru should I receive instruction? By whom should I have Your value appraised? ||1||", hindi = "कउणु गुरू. कै पहि दीखिआ लेवा; कै पहि मुलु करावा ॥१॥", punjabi = "ਮੈਨੂੰ ਕੋਈ ਐਸਾ ਉਸਤਾਦ ਨਹੀਂ ਦਿੱਸਦਾ ਜਿਸ ਪਾਸੋਂ ਮੈਂ ਤੇਰਾ ਮੁੱਲ ਪਵਾ ਸਕਾਂ ਜਾਂ ਮੁੱਲ ਪਾਣ ਦੀ ਜਾਚ ਸਿੱਖ ਸਕਾਂ ॥੧॥", wordMeaning = "ਕੈ ਪਹਿ = ਕਿਸ ਪਾਸੋਂ? ਦੀਖਿਆ = ਸਿੱਖਿਆ। ਲੇਵਾ = ਮੈਂ ਲਵਾਂ। ਮੁਲੁ ਕਰਾਵਾ = ਮੈਂ ਕੀਮਤ ਪਵਾਵਾਂ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-72", gurmukhi = "ਮੇਰੇ ਲਾਲ ਜੀਉ; ਤੇਰਾ ਅੰਤੁ. ਨ ਜਾਣਾ ॥", transliteration = "mere laal jeeu; teraa ant. na jaanaa ||", translation = "O my Dear Beloved Lord, Your limits are not known.", hindi = "मेरे लाल जीउ; तेरा अंतु. न जाणा ॥", punjabi = "ਹੇ ਮੇਰੇ ਸੋਹਣੇ ਪ੍ਰਭੂ ਜੀ! ਮੈਂ ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਜਾਣ ਸਕਦਾ (ਮੈਨੂੰ ਇਹ ਸਮਝ ਨਹੀਂ ਆ ਸਕਦੀ ਕਿ ਤੇਰੇ ਵਿਚ ਕਿਤਨੀਆਂ ਕੁ ਸਿਫ਼ਤਾਂ ਹਨ)।", wordMeaning = "ਲਾਲ = ਹੇ ਲਾਲ! ਨ ਜਾਣਾ = ਮੈਂ ਨਹੀਂ ਜਾਣਦਾ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-73", gurmukhi = "ਤੂੰ ਜਲਿ ਥਲਿ ਮਹੀਅਲਿ ਭਰਿਪੁਰਿ ਲੀਣਾ; ਤੂੰ ਆਪੇ ਸਰਬ ਸਮਾਣਾ ॥੧॥ ਰਹਾਉ ॥", transliteration = "toon jal thal mheeal bhripur leenaa; toon aape sarab smaanaa ||1|| rhaau ||", translation = "You pervade the water, the land, and the sky; You Yourself are All-pervading. ||1||Pause||", hindi = "तूं जलि थलि महीअलि भरिपुरि लीणा; तूं आपे सरब समाणा ॥१॥ रहाउ ॥", punjabi = "ਤੂੰ ਪਾਣੀ ਵਿਚ ਭਰਪੂਰ ਹੈਂ, ਤੂੰ ਧਰਤੀ ਦੇ ਅੰਦਰ ਵਿਆਪਕ ਹੈਂ, ਤੂੰ ਆਕਾਸ਼ ਵਿਚ ਹਰ ਥਾਂ ਮੌਜੂਦ ਹੈਂ, ਤੂੰ ਆਪ ਹੀ ਸਭ ਜੀਵਾਂ ਵਿਚ ਸਭ ਥਾਵਾਂ ਵਿਚ ਸਮਾਇਆ ਹੋਇਆ ਹੈਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਜਲਿ = ਜਲ ਵਿਚ। ਥਲਿ = ਧਰਤੀ ਦੇ ਅੰਦਰ। ਮਹੀਅਲਿ = ਮਹੀ ਤਲਿ, ਧਰਤੀ ਦੇ ਤਲ ਉਤੇ, ਪੁਲਾੜ ਵਿਚ, ਆਕਾਸ਼ ਵਿਚ। ਭਰਿਪੁਰਿ = ਭਰਪੂਰ। ਲੀਣਾ = ਵਿਆਪਕ। ਆਪੇ = ਆਪ ਹੀ ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-74", gurmukhi = "ਮਨੁ ਤਾਰਾਜੀ. ਚਿਤੁ ਤੁਲਾ; ਤੇਰੀ ਸੇਵ ਸਰਾਫੁ ਕਮਾਵਾ ॥", transliteration = "man taaraajee. chit tulaa; teree sev sraaph kmaavaa ||", translation = "Mind is the scale, consciousness the weights, and the performance of Your service is the appraiser.", hindi = "मनु ताराजी. चितु तुला; तेरी सेव सराफु कमावा ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਜੇ ਮੇਰਾ ਮਨ ਤੱਕੜੀ ਬਣ ਜਾਏ, ਜੇ ਮੇਰਾ ਚਿੱਤ ਤੋਲਣ ਵਾਲਾ ਵੱਟਾ ਬਣ ਜਾਏ, ਜੇ ਮੈਂ ਤੇਰੀ ਸੇਵਾ ਕਰ ਸਕਾਂ, ਤੇਰਾ ਸਿਮਰਨ ਕਰ ਸਕਾਂ (ਜੇ ਇਹ ਸੇਵਾ-ਸਿਮਰਨ ਮੇਰੇ ਵਾਸਤੇ) ਸਰਾਫ਼ ਬਣ ਜਾਏ,", wordMeaning = "ਤਾਰਾਜੀ = ਤੱਕੜੀ। ਤੇਰੀ ਸੇਵ ਕਮਾਵਾ = ਮੈਂ ਤੇਰੀ ਸੇਵਾ ਕਰਾਂ, ਮੈਂ ਤੇਰਾ ਸਿਮਰਨ ਕਰਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-75", gurmukhi = "ਘਟ ਹੀ ਭੀਤਰਿ. ਸੋ ਸਹੁ ਤੋਲੀ; ਇਨ ਬਿਧਿ ਚਿਤੁ ਰਹਾਵਾ ॥੨॥", transliteration = "ghat hee bheetar. so sah tolee; in bidh chit rhaavaa ||2||", translation = "Deep within my heart, I weigh my Husband Lord; in this way I focus my consciousness. ||2||", hindi = "घट ही भीतरि. सो सहु तोली; इन बिधि चितु रहावा ॥२॥", punjabi = "(ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਮੈਂ ਅੰਤ ਤਾਂ ਨਹੀਂ ਪਾ ਸਕਾਂਗਾ, ਪਰ) ਇਹਨਾਂ ਤਰੀਕਿਆਂ ਨਾਲ ਮੈਂ ਆਪਣੇ ਚਿੱਤ ਨੂੰ ਤੇਰੇ ਚਰਨਾਂ ਵਿਚ ਟਿਕਾ ਕੇ ਰੱਖ ਸਕਾਂਗਾ। (ਹੇ ਭਾਈ!) ਮੈਂ ਆਪਣੇ ਹਿਰਦੇ ਵਿਚ ਹੀ ਉਸ ਖਸਮ-ਪ੍ਰਭੂ ਨੂੰ ਬੈਠਾ ਜਾਚ ਸਕਾਂਗਾ ॥੨॥", wordMeaning = "ਘਟ = ਹਿਰਦਾ। ਭੀਤਰਿ = ਅੰਦਰ। ਸਹੁ = ਖਸਮ-ਪ੍ਰਭੂ। ਤੋਲੀ = ਮੈਂ ਤੋਲਾਂ, ਪਰਖ ਕਰਾਂ। ਇਨ੍ਹ੍ਹ ਬਿਧਿ = ਇਹਨਾਂ ਤਰੀਕਿਆਂ ਨਾਲ। ਰਹਾਵਾ = ਮੈਂ ਟਿਕਾਵਾਂ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-76", gurmukhi = "ਆਪੇ ਕੰਡਾ ਤੋਲੁ ਤਰਾਜੀ; ਆਪੇ ਤੋਲਣਹਾਰਾ ॥", transliteration = "aape kandaa tol traajee; aape tolanhaaraa ||", translation = "You Yourself are the balance, the weights and the scale; You Yourself are the weigher.", hindi = "आपे कंडा तोलु तराजी; आपे तोलणहारा ॥", punjabi = "(ਹੇ ਭਾਈ! ਪ੍ਰਭੂ ਹਰੇਕ ਥਾਂ ਵਿਆਪਕ ਹੈ, ਆਪਣੀ ਵਡਿਆਈ ਭੀ ਉਹ ਆਪ ਹੀ ਜਾਣਦਾ ਹੈ ਤੇ ਜਾਚ ਸਕਦਾ ਹੈ ਉਹ) ਆਪ ਹੀ ਤੱਕੜੀ ਹੈ, ਤੱਕੜੀ ਦਾ ਵੱਟਾ ਹੈ, ਤੱਕੜੀ ਦੀ ਬੋਦੀ ਹੈ, ਉਹ ਆਪ ਹੀ (ਆਪਣੇ ਗੁਣਾਂ ਨੂੰ) ਤੋਲਣ ਵਾਲਾ ਹੈ।", wordMeaning = "ਕੰਡਾ = ਤੱਕੜੀ ਦੀ ਡੰਡੀ ਦੇ ਅੱਧ ਵਿਚ ਦੀ ਸੂਈ, ਤੱਕੜੀ ਦੀ ਬੋਦੀ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-77", gurmukhi = "ਆਪੇ ਦੇਖੈ ਆਪੇ ਬੂਝੈ; ਆਪੇ ਹੈ ਵਣਜਾਰਾ ॥੩॥", transliteration = "aape dekhai aape boojhai; aape hai vanjaaraa ||3||", translation = "You Yourself see, and You Yourself understand; You Yourself are the trader. ||3||", hindi = "आपे देखै आपे बूझै; आपे है वणजारा ॥३॥", punjabi = "ਉਹ ਆਪ ਹੀ ਸਭ ਜੀਵਾਂ ਦੀ ਸੰਭਾਲ ਕਰਦਾ ਹੈ, ਆਪ ਹੀ ਸਭ ਦੇ ਦਿਲਾਂ ਦੀ ਸਮਝਦਾ ਹੈ, ਆਪ ਹੀ ਜੀਵ-ਰੂਪ ਹੋ ਕੇ ਜਗਤ ਵਿਚ (ਨਾਮ) ਵਣਜ ਕਰ ਰਿਹਾ ਹੈ ॥੩॥", wordMeaning = "ਦੇਖੈ = ਸੰਭਾਲ ਕਰਦਾ ਹੈ। ਬੂਝੈ = ਸਮਝਦਾ ਹੈ। ਵਣਜਾਰਾ = ਵਣਜ ਕਰਨ ਵਾਲਾ ਜੀਵ-ਵਪਾਰੀ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-78", gurmukhi = "ਅੰਧੁਲਾ ਨੀਚ ਜਾਤਿ ਪਰਦੇਸੀ; ਖਿਨੁ ਆਵੈ ਤਿਲੁ ਜਾਵੈ ॥", transliteration = "andhulaa neech jaat pardesee; khin aavai til jaavai ||", translation = "The blind, low class wandering soul, comes for a moment, and departs in an instant.", hindi = "अंधुला नीच जाति परदेसी; खिनु आवै तिलु जावै ॥", punjabi = "ਜੋ (ਮਨ ਮਾਇਆ ਦੇ ਮੋਹ ਵਿਚ) ਅੰਨ੍ਹਾ ਹੋਇਆ ਪਿਆ ਹੈ ਜੋ (ਜਨਮਾਂ ਜਨਮਾਂਤਰਾਂ ਦੇ ਵਿਕਾਰਾਂ ਦੀ ਮੈਲ ਨਾਲ) ਨੀਵੀਂ ਜਾਤਿ ਦਾ ਬਣਿਆ ਹੋਇਆ ਹੈ, ਜੋ ਸਦਾ ਭਟਕਦਾ ਰਹਿੰਦਾ ਹੈ, ਰਤਾ ਮਾਤ੍ਰ ਭੀ ਕਿਤੇ ਇਕ ਥਾਂ ਟਿਕ ਨਹੀਂ ਸਕਦਾ", wordMeaning = "ਅੰਧੁਲਾ = ਅੰਨ੍ਹਾ । ਨੀਚ ਜਾਤਿ = ਨੀਵੀਂ ਜਾਤਿ ਵਾਲਾ। ਪਰਦੇਸੀ = ਭਟਕਦਾ ਰਹਿਣ ਵਾਲਾ। ਖਿਨੁ = ਅੱਖ ਦੇ ਝਮਕਣ ਜਿਤਨੇ ਸਮੇ ਵਿਚ। ਤਿਲੁ = ਰਤਾ ਭਰ ਸਮੇ ਵਿਚ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-79", gurmukhi = "ਤਾ ਕੀ ਸੰਗਤਿ ਨਾਨਕੁ ਰਹਦਾ; ਕਿਉ ਕਰਿ ਮੂੜਾ ਪਾਵੈ ॥੪॥੨॥੯॥", transliteration = "taa kee sangat naanak rahdaa; kiu kar mooraa paavai ||4||2||9||", translation = "In its company, Nanak dwells; how can the fool attain the Lord? ||4||2||9||", hindi = "ता की संगति नानकु रहदा; किउ करि मूड़ा पावै ॥४॥२॥९॥", punjabi = "ਨਾਨਕ ਦੀ ਸੰਗਤਿ ਸਦਾ ਉਸ ਮਨ ਨਾਲ ਹੈ, ਜਿਸ ਕਰ ਕੇ ਅੰਞਾਣ ਨਾਨਕ ਪਰਮਾਤਮਾ ਦੇ ਗੁਣਾਂ ਦੀ ਕਦਰ ਨਹੀਂ ਪਾ ਸਕਦਾ ॥੪॥੨॥੯॥", wordMeaning = "ਤਾ ਕੀ = ਅਜੇਹੇ (ਮਨ) ਦੀ। ਕਿਉ ਕਰਿ = ਕਿਸ ਤਰ੍ਹਾਂ? ਮੂੜਾ = ਮੂਰਖ। ਪਾਵੈ = (ਕਦਰ) ਪਾ ਸਕਦਾ ਹੈ ॥੪॥੨॥੯॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-80", gurmukhi = "ੴ ਸਤਿ ਨਾਮੁ ਕਰਤਾ ਪੁਰਖੁ ਨਿਰਭਉ ਨਿਰਵੈਰੁ ਅਕਾਲ ਮੂਰਤਿ ਅਜੂਨੀ ਸੈਭੰ ਗੁਰ ਪ੍ਰਸਾਦਿ ॥", transliteration = "ik oankar sat naam kartaa purakh nirabhau nirvair akaal moorat ajoonee saibhan gur prasaad ||", translation = "One Universal Creator God. Truth Is The Name. Creative Being Personified. No Fear. No Hatred. Image Of The Undying. Beyond Birth. Self-Existent. By Guru's Grace:", hindi = "एकओंकार सति नामु करता पुरखु निरभउ निरवैरु अकाल मूरति अजूनी सैभं गुर प्रसादि ॥", punjabi = "ਅਕਾਲ ਪੁਰਖ ਇੱਕ ਹੈ, ਜਿਸ ਦਾ ਨਾਮ 'ਹੋਂਦ ਵਾਲਾ' ਹੈ ਜੋ ਸ੍ਰਿਸ਼ਟੀ ਦਾ ਰਚਨਹਾਰ ਹੈ, ਜੋ ਸਭ ਵਿਚ ਵਿਆਪਕ ਹੈ, ਭੈ ਤੋਂ ਰਹਿਤ ਹੈ, ਵੈਰ-ਰਹਿਤ ਹੈ, ਜਿਸ ਦਾ ਸਰੂਪ ਕਾਲ ਤੋਂ ਪਰੇ ਹੈ, (ਭਾਵ, ਜਿਸ ਦਾ ਸਰੀਰ ਨਾਸ-ਰਹਿਤ ਹੈ), ਜੋ ਜੂਨਾਂ ਵਿਚ ਨਹੀਂ ਆਉਂਦਾ, ਜਿਸ ਦਾ ਪ੍ਰਕਾਸ਼ ਆਪਣੇ ਆਪ ਤੋਂ ਹੋਇਆ ਹੈ ਅਤੇ ਜੋ ਸਤਿਗੁਰੂ ਦੀ ਕਿਰਪਾ ਨਾਲ ਮਿਲਦਾ ਹੈ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-81", gurmukhi = "ਰਾਗੁ ਬਿਲਾਵਲੁ ਮਹਲਾ ੧ ਚਉਪਦੇ ਘਰੁ ੧ ॥", transliteration = "raag bilaaval mahlaa 1 chaupde ghar 1 ||", translation = "Raag Bilaaval, First Mehl, Chau-Padhay, First House:", hindi = "रागु बिलावलु महला १ चउपदे घरु १ ॥", punjabi = "ਰਾਗ ਬਿਲਾਵਲੁ, ਘਰ ੧ ਵਿੱਚ ਗੁਰੂ ਨਾਨਕਦੇਵ ਜੀ ਦੀ ਚਾਰ-ਬੰਦਾਂ ਵਾਲੀ ਬਾਣੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-82", gurmukhi = "ਤੂ ਸੁਲਤਾਨੁ. ਕਹਾ ਹਉ ਮੀਆ; ਤੇਰੀ ਕਵਨ ਵਡਾਈ ॥", transliteration = "too sultaan. khaa hau meeaa; teree kavan vdaaee ||", translation = "You are the Emperor, and I call You a chief - how does this add to Your greatness?", hindi = "तू सुलतानु. कहा हउ मीआ; तेरी कवन वडाई ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰ ਕੇ ਮੈਂ ਤੇਰੀ ਵਡਿਆਈ ਨਹੀਂ ਕਰ ਰਿਹਾ, (ਇਹ ਤਾਂ ਇਉਂ ਹੀ ਹੈ ਕਿ) ਤੂੰ ਬਾਦਸ਼ਾਹ ਹੈਂ, ਤੇ ਮੈਂ ਤੈਨੂੰ ਮੀਆਂ ਆਖ ਰਿਹਾ ਹਾਂ।", wordMeaning = "ਕਹਾ ਹਉ = ਮੈਂ ਆਖਦਾ ਹਾਂ। ਕਵਨ ਵਡਾਈ = ਕੋਈ ਵਡਿਆਈ ਨਹੀਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-83", gurmukhi = "ਜੋ ਤੂ ਦੇਹਿ. ਸੁ ਕਹਾ ਸੁਆਮੀ; ਮੈ ਮੂਰਖ. ਕਹਣੁ ਨ ਜਾਈ ॥੧॥", transliteration = "jo too deh. su khaa suaamee; mai moorakh. kahan na jaaee ||1||", translation = "As You permit me, I praise You, O Lord and Master; I am ignorant, and I cannot chant Your Praises. ||1||", hindi = "जो तू देहि. सु कहा सुआमी; मै मूरख. कहणु न जाई ॥१॥", punjabi = "(ਪਰ ਇਤਨੀ ਕੁ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰਨੀ ਮੇਰੀ ਆਪਣੀ ਸਮਰੱਥਾ ਨਹੀਂ ਹੈ) ਹੇ ਮਾਲਕ-ਪ੍ਰਭੂ! (ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰਨ ਦਾ) ਜਿਤਨਾ ਕੁ ਬਲ ਤੂੰ ਦੇਂਦਾ ਹੈਂ ਮੈਂ ਉਤਨਾ ਕੁ ਤੇਰੇ ਗੁਣ ਆਖ ਲੈਂਦਾ ਹਾਂ। ਮੈਂ ਅੰਞਾਣ ਪਾਸੋਂ ਤੇਰੇ ਗੁਣ ਬਿਆਨ ਨਹੀਂ ਹੋ ਸਕਦੇ ॥੧॥", wordMeaning = "ਕਹਾ = ਮੈਂ ਆਖਦਾ ਹਾਂ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-84", gurmukhi = "ਤੇਰੇ ਗੁਣ ਗਾਵਾ; ਦੇਹਿ ਬੁਝਾਈ ॥", transliteration = "tere gun gaavaa; deh bujhaaee ||", translation = "Please bless me with such understanding, that I may sing Your Glorious Praises.", hindi = "तेरे गुण गावा; देहि बुझाई ॥", punjabi = "ਹੇ ਪ੍ਰਭੂ! ਮੈਨੂੰ (ਅਜੇਹੀ) ਸਮਝ ਬਖ਼ਸ਼ ਕਿ ਮੈਂ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰ ਸਕਾਂ।", wordMeaning = "ਗਾਵਾ = ਮੈਂ ਗਾਵਾਂ। ਬੁਝਾਈ = ਸਮਝ, ਅਕਲ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-85", gurmukhi = "ਜੈਸੇ ਸਚ ਮਹਿ; ਰਹਉ ਰਜਾਈ ॥੧॥ ਰਹਾਉ ॥", transliteration = "jaise sach mah; rahau rjaaee ||1|| rhaau ||", translation = "May I dwell in Truth, according to Your Will. ||1||Pause||", hindi = "जैसे सच महि; रहउ रजाई ॥१॥ रहाउ ॥", punjabi = "ਹੇ ਰਜ਼ਾ ਦੇ ਮਾਲਕ-ਪ੍ਰਭੂ! ਤੂੰ ਸਦਾ ਕਾਇਮ ਰਹਿਣ ਵਾਲਾ ਹੈਂ ਤੇ, ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦੀ ਬਰਕਤਿ ਨਾਲ ਮੈਂ ਤੇਰੇ (ਚਰਨਾਂ) ਵਿਚ ਟਿਕਿਆ ਰਹਿ ਸਕਾਂ ॥੧॥ ਰਹਾਉ ॥", wordMeaning = "ਜੈਸੇ = ਜਿਸ ਤਰ੍ਹਾਂ, ਤਾਂ ਜੋ। ਰਹਉ = ਮੈਂ ਟਿਕਿਆ ਰਹਾਂ। ਰਜਾਈ = ਹੇ ਰਜ਼ਾ ਦੇ ਮਾਲਕ-ਪ੍ਰਭੂ! ॥੧॥ ਰਹਾਉ ॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-86", gurmukhi = "ਜੋ ਕਿਛੁ ਹੋਆ. ਸਭੁ ਕਿਛੁ ਤੁਝ ਤੇ; ਤੇਰੀ ਸਭ ਅਸਨਾਈ ॥", transliteration = "jo kichh hoaa. sabh kichh tujh te; teree sabh asnaaee ||", translation = "Whatever has happened, has all come from You. You are All-knowing.", hindi = "जो किछु होआ. सभु किछु तुझ ते; तेरी सभ असनाई ॥", punjabi = "ਇਹ ਜਿਤਨਾ ਕੁ ਜਗਤ ਬਣਿਆ ਹੋਇਆ ਹੈ ਇਹ ਸਾਰਾ ਤੈਥੋਂ ਹੀ ਬਣਿਆ ਹੈ, ਇਹ ਸਾਰੀ ਤੇਰੀ ਹੀ ਬਜ਼ੁਰਗੀ ਹੈ।", wordMeaning = "ਤੁਝ ਤੇ = ਤੈਥੋਂ। ਅਸਨਾਈ = ਨਾਈ, ਵਡਿਆਈ {'ਸ੍ਨਾ' ਅਰਬੀ ਲਫ਼ਜ਼ ਹੈ, ਅਰਥ ਹੈ 'ਵਡਿਆਈ'}। {ਨੋਟ: ਜਦੋਂ ਕਿਸੇ ਲਫ਼ਜ਼ ਦੇ ਸ਼ੁਰੂ ਵਿਚ ਦੋ ਜੁੜਵੇਂ ਅੱਖਰ ਹੋਣ ਜਿਨ੍ਹਾਂ ਵਿਚ ਪਹਿਲਾ ਅੱਖਰ 'ਸ' ਹੋਵੇ, ਤਾਂ ਪੰਜਾਬੀ-ਉਚਾਰਨ ਵਿਚ ਉਹਨਾਂ ਦੋਹਾਂ ਅੱਖਰਾਂ ਨੂੰ ਵਖ ਵਖ ਕਰ ਕੇ 'ਸ' ਦੇ ਪਹਿਲਾਂ 'ਅ' ਵਰਤ ਲਈਦਾ ਹੈ। ਜਾਂ, 'ਸ' ਉਡਾ ਹੀ ਦੇਈਦਾ ਹੈ; ਜਿਵੇਂ: (स्थान) ਸਾਨ = ਅਸਥਾਨ, ਥਾਨ। (स्तम्भ) ਸ੍ਤੰਭ = ਅਸਥੰਭ, ਥੰਭ, ਥੰਮ੍ਹ੍ਹ। (स्टेशन) ਸ੍ਟੇਸ਼ਨ = ਅਸਟੇਸ਼ਨ, ਟੇਸ਼ਨ। (स्ना) ਸ੍ਨਾ = ਅਸਨਾਈ, ਨਾਈ (ਅਰਬੀ ਲਫ਼ਜ਼)}।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-87", gurmukhi = "ਤੇਰਾ ਅੰਤੁ. ਨ ਜਾਣਾ ਮੇਰੇ ਸਾਹਿਬ; ਮੈ ਅੰਧੁਲੇ. ਕਿਆ ਚਤੁਰਾਈ ॥੨॥", transliteration = "teraa ant. na jaanaa mere saahib; mai andhule. kiaa chturaaee ||2||", translation = "Your limits cannot be known, O my Lord and Master; I am blind - what wisdom do I have? ||2||", hindi = "तेरा अंतु. न जाणा मेरे साहिब; मै अंधुले. किआ चतुराई ॥२॥", punjabi = "ਹੇ ਮਾਲਕ-ਪ੍ਰਭੂ! ਮੈਂ ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਤ ਨਹੀਂ ਜਾਣ ਸਕਦਾ। ਮੈਂ ਅੰਨ੍ਹਾ ਹਾਂ (ਤੁੱਛ-ਅਕਲ ਹਾਂ) ਮੇਰੇ ਵਿਚ ਕੋਈ ਐਸੀ ਸਿਆਣਪ ਨਹੀਂ ਹੈ (ਕਿ ਮੈਂ ਤੇਰੇ ਗੁਣਾਂ ਦਾ ਅੰਤ ਜਾਣ ਸਕਾਂ ॥੨॥", wordMeaning = "ਸਾਹਿਬ = ਹੇ ਸਾਹਿਬ! ਚਤੁਰਾਈ = ਅਕਲ, ਚਲਾਕੀ ॥੨॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-88", gurmukhi = "ਕਿਆ ਹਉ ਕਥੀ. ਕਥੇ ਕਥਿ ਦੇਖਾ; ਮੈ. ਅਕਥੁ, ਨ ਕਥਨਾ ਜਾਈ ॥", transliteration = "kiaa hau kthee. kthe kath dekhaa; mai. akath, na kathnaa jaaee ||", translation = "What should I say? While talking, I talk of seeing, but I cannot describe the indescribable.", hindi = "किआ हउ कथी. कथे कथि देखा; मै. अकथु, न कथना जाई ॥", punjabi = "ਮੈਂ ਤੇਰੇ ਗੁਣ ਬਿਲਕੁਲ ਨਹੀਂ ਕਹਿ ਸਕਦਾ। ਤੇਰੇ ਗੁਣ ਆਖ ਆਖ ਕੇ ਜਦੋਂ ਮੈਂ ਵੇਖਦਾ ਹਾਂ (ਤਾਂ ਮੈਨੂੰ ਸਮਝ ਪੈਂਦੀ ਹੈ ਕਿ) ਤੇਰਾ ਸਰੂਪ ਬਿਆਨ ਤੋਂ ਪਰੇ ਹੈ, ਮੈਂ ਬਿਆਨ ਕਰਨ ਜੋਗਾ ਨਹੀਂ ਹਾਂ।", wordMeaning = "ਹਉ = ਮੈਂ। ਕਥੀ = ਮੈਂ ਬਿਆਨ ਕਰਾਂ। ਕਥੇ ਕਥਿ = ਕਥਿ ਕਥਿ, ਕਥ ਕੇ ਕਥ ਕੇ। ਦੇਖਾ = ਮੈਂ ਵੇਖਦਾ ਹਾਂ। ਅਕਥੁ = ਜਿਸ ਦੇ ਗੁਣ ਕਹੇ ਨ ਜਾ ਸਕਣ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-89", gurmukhi = "ਜੋ ਤੁਧੁ ਭਾਵੈ. ਸੋਈ ਆਖਾ; ਤਿਲੁ ਤੇਰੀ ਵਡਿਆਈ ॥੩॥", transliteration = "jo tudh bhaavai. soee aakhaa; til teree vdiaaee ||3||", translation = "As it pleases Your Will, I speak; it is just the tiniest bit of Your greatness. ||3||", hindi = "जो तुधु भावै. सोई आखा; तिलु तेरी वडिआई ॥३॥", punjabi = "ਤੇਰੀ ਰਤਾ ਮਾਤ੍ਰ ਵਡਿਆਈ ਭੀ ਜੇਹੜੀ ਮੈਂ ਆਖਦਾ ਹਾਂ ਉਹੀ ਆਖਦਾ ਹਾਂ ਜੋ ਤੈਨੂੰ ਭਾਉਂਦੀ ਹੈ (ਭਾਵ, ਜਿਤਨੀ ਕੁ ਤੂੰ ਬਿਆਨ ਕਰਨ ਲਈ ਆਪ ਹੀ ਸਮਝ ਦੇਂਦਾ ਹੈਂ) ॥੩॥", wordMeaning = "ਤਿਲੁ = ਰਤਾ ਕੁ ॥੩॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-90", gurmukhi = "ਏਤੇ ਕੂਕਰ ਹਉ. ਬੇਗਾਨਾ; ਭਉਕਾ. ਇਸੁ ਤਨ ਤਾਈ ॥", transliteration = "ete kookar hau. begaanaa; bhaukaa. is tan taaee ||", translation = "Among so many dogs, I am an outcast; I bark for my body's belly.", hindi = "एते कूकर हउ. बेगाना; भउका. इसु तन ताई ॥", punjabi = "(ਹੇ ਪ੍ਰਭੂ! ਇਥੇ ਕਾਮਾਦਿਕ) ਅਨੇਕਾਂ ਕੁੱਤੇ ਹਨ, ਮੈਂ (ਇਹਨਾਂ ਵਿਚ) ਓਪਰਾ (ਆ ਫਸਿਆ) ਹਾਂ, (ਜਿਤਨੀ ਕੁ ਤੇਰੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਕਰਦਾ ਹਾਂ ਉਹ ਭੀ ਮੈਂ) ਆਪਣੇ ਇਸ ਸਰੀਰ ਨੂੰ (ਕਾਮਾਦਿਕ ਕੁੱਤਿਆਂ ਤੋਂ ਬਚਾਣ ਲਈ ਭੌਂਕਦਾ ਹੀ ਹਾਂ, ਜਿਵੇਂ ਓਪਰਾ ਕੁੱਤਾ ਵੈਰੀ ਕੁੱਤਿਆਂ ਤੋਂ ਬਚਣ ਲਈ ਭੌਂਕਦਾ ਹੈ)।", wordMeaning = "ਏਤੇ = ਇਤਨੇ, ਅਨੇਕਾਂ। ਕੂਕਰ = ਕੁੱਤੇ, ਕਾਮਾਦਿਕ ਵਿਕਾਰ। ਬੇਗਾਨਾ = ਓਪਰਾ। ਭਉਕਾ = ਮੈਂ ਭੌਂਕਦਾ ਹਾਂ। ਇਸੁ ਤਨ ਤਾਈ = ਇਸ ਸਰੀਰ ਨੂੰ ਬਚਾਣ ਵਾਸਤੇ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-91", gurmukhi = "ਭਗਤਿ ਹੀਣੁ ਨਾਨਕੁ. ਜੇ ਹੋਇਗਾ; ਤਾ ਖਸਮੈ ਨਾਉ. ਨ ਜਾਈ ॥੪॥੧॥", transliteration = "bhagat heen naanak. je hoigaa; taa khasmai naau. na jaaee ||4||1||", translation = "Without devotional worship, O Nanak, even so, still, my Master's Name does not leave me. ||4||1||", hindi = "भगति हीणु नानकु. जे होइगा; ता खसमै नाउ. न जाई ॥४॥१॥", punjabi = "(ਮੈਨੂੰ ਇਹ ਧਰਵਾਸ ਹੈ ਕਿ) ਜੇ (ਤੇਰਾ ਦਾਸ) ਨਾਨਕ ਭਗਤੀ ਤੋਂ ਸੱਖਣਾ ਹੈ (ਤਾਂ ਭੀ ਤੂੰ ਮੇਰੇ ਸਿਰ ਤੇ ਰਾਖਾ ਖਸਮ ਹੈਂ, ਤੇ ਤੈਂ) ਖਸਮ ਦੀ ਇਹ ਸੋਭਾ ਦੂਰ ਨਹੀਂ ਹੋ ਗਈ (ਕਿ ਤੂੰ ਮੁੱਢ ਕਦੀਮਾਂ ਤੋਂ ਸਰਨ ਆਏ ਦੀ ਸਹੈਤਾ ਕਰਦਾ ਆਇਆ ਹੈਂ) ॥੪॥੧॥", wordMeaning = "ਖਸਮੈ ਨਾਉ = ਖਸਮ ਦਾ ਨਾਮ, ਖਸਮ ਦੀ ਬਜ਼ੁਰਗੀ, ਖਸਮ ਦੀ ਵਡਿਆਈ। ਨ ਜਾਈ = ਦੂਰ ਨਹੀਂ ਹੋ ਸਕਦੀ ॥੪॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-92", gurmukhi = "ਬਿਲਾਵਲੁ ਮਹਲਾ ੧ ॥", transliteration = "bilaaval mahlaa 1 ||", translation = "Bilaawal, First Mehl:", hindi = "बिलावलु महला १ ॥", punjabi = "ਬਿਲਾਵਲ ਪਹਿਲੀ ਪਾਤਿਸ਼ਾਹੀ।", wordMeaning = "", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-93", gurmukhi = "ਮਨੁ ਮੰਦਰੁ. ਤਨੁ ਵੇਸ ਕਲੰਦਰੁ; ਘਟ ਹੀ ਤੀਰਥਿ ਨਾਵਾ ॥", transliteration = "man mandar. tan ves kalandar; ghat hee teerath naavaa ||", translation = "My mind is the temple, and my body is the simple cloth of the humble seeker; deep within my heart, I bathe at the sacred shrine.", hindi = "मनु मंदरु. तनु वेस कलंदरु; घट ही तीरथि नावा ॥", punjabi = "ਮੇਰਾ ਮਨ (ਪ੍ਰਭੂ-ਦੇਵ ਦੇ ਰਹਿਣ ਲਈ) ਮੰਦਰ (ਬਣ ਗਿਆ) ਹੈ, ਮੇਰਾ ਸਰੀਰ (ਭਾਵ, ਮੇਰਾ ਹਰੇਕ ਗਿਆਨ-ਇੰਦ੍ਰਾ ਮੰਦਰ ਦੀ ਜਾਤ੍ਰਾ ਕਰਨ ਵਾਲਾ) ਰਮਤਾ ਸਾਧੂ ਬਣ ਗਿਆ ਹੈ (ਭਾਵ, ਮੇਰੇ ਗਿਆਨ-ਇੰਦ੍ਰੇ ਬਾਹਰ ਭਟਕਣ ਦੇ ਥਾਂ ਅੰਦਰ-ਵੱਸਦੇ ਪਰਮਾਤਮਾ ਵਲ ਪਰਤ ਪਏ ਹਨ), ਹੁਣ ਮੈਂ ਹਿਰਦੇ-ਤੀਰਥ ਉਤੇ ਹੀ ਇਸ਼ਨਾਨ ਕਰਦਾ ਹਾਂ।", wordMeaning = "ਮੰਦਰੁ = ਦੇਵਤੇ ਦਾ ਅਸਥਾਨ। ਤਨੁ = ਸਰੀਰ (ਭਾਵ, ਗਿਆਨ-ਇੰਦ੍ਰੇ)। ਵੇਸ ਕਲੰਦਰੁ = ਫ਼ਕੀਰੀ ਪਹਿਰਾਵੇ ਵਾਲਾ। ਕਲੰਦਰ = ਫ਼ਕੀਰ, ਰਮਤਾ ਫ਼ਕੀਰ। ਘਟ ਹੀ = ਘਟਿ ਹੀ, ਹਿਰਦੇ ਵਿਚ ਹੀ। ਤੀਰਥਿ = ਤੀਰਥ ਉਤੇ। ਨਾਵਾ = ਮੈਂ ਨ੍ਹਾਉਂਦਾ ਹਾਂ।", startsAtMs = 0L, endsAtMs = 0L),
    BaniLine(id = "shabad-hazare-94", gurmukhi = "ਏਕੁ ਸਬਦੁ ਮੇਰੈ ਪ੍ਰਾਨਿ ਬਸਤੁ ਹੈ; ਬਾਹੁੜਿ ਜਨਮਿ. ਨ ਆਵਾ ॥੧॥", transliteration = "ek sabad merai praan basat hai; baahur janam. na aavaa ||1||", translation = "The One Word of the Shabad abides within my mind; I shall not come to be born again. ||1||", hindi = "एकु सबदु मेरै प्रानि बसतु है; बाहुड़ि जनमि. न आवा ॥१॥", punjabi = "ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦਾ ਸ਼ਬਦ ਮੇਰੀ ਜਿੰਦ ਵਿਚ ਟਿਕ ਗਿਆ ਹੈ (ਮੇਰੀ ਜਿੰਦ ਦਾ ਆਸਰਾ ਬਣ ਗਿਆ। ਇਸ ਵਾਸਤੇ ਮੈਨੂੰ ਯਕੀਨ ਹੋ ਗਿਆ ਹੈ ਕਿ) ਮੈਂ ਮੁੜ ਜਨਮ ਵਿਚ ਨਹੀਂ ਆਵਾਂਗਾ ॥੧॥", wordMeaning = "ਏਕੁ ਸਬਦੁ = ਪਰਮਾਤਮਾ ਦੀ ਸਿਫ਼ਤਿ-ਸਾਲਾਹ ਦਾ ਸ਼ਬਦ। ਮੇਰੈ ਪ੍ਰਾਨਿ = ਮੇਰੀ ਜਿੰਦ ਵਿਚ। ਜਨਮਿ = ਜਨਮ ਵਿਚ। ਬਾਹੁੜਿ = ਮੁੜ, ਫਿਰ। ਆਵਾ = ਆਵਾਂਗਾ ॥੧॥", startsAtMs = 0L, endsAtMs = 0L),
